import {
  addDoc,
  collection,
  getDocs,
  limit,
  orderBy,
  query,
  serverTimestamp,
  where,
} from "firebase/firestore";
import type { AuditAction, AuditEntityType } from "../../features/admin/types";

export type WriteAuditInput = {
  entityType: AuditEntityType;
  entityId: string;
  action: AuditAction;
  before?: Record<string, unknown>;
  after?: Record<string, unknown>;
  performedBy: string;
};

async function getDb() {
  const { db } = await import("../../lib/firebase");
  return db;
}

export async function writeAuditLog(input: WriteAuditInput): Promise<void> {
  const db = await getDb();
  await addDoc(collection(db, "auditLogs"), {
    entityType: input.entityType,
    entityId: input.entityId,
    action: input.action,
    before: input.before ?? null,
    after: input.after ?? null,
    performedBy: input.performedBy,
    performedAt: serverTimestamp(),
  });
}

export type AuditLogEntry = {
  id: string;
  entityType: AuditEntityType;
  entityId: string;
  action: AuditAction;
  before: Record<string, unknown> | null;
  after: Record<string, unknown> | null;
  performedBy: string;
  performedAt: unknown;
};

export async function listAuditLogs(maxResults = 100): Promise<AuditLogEntry[]> {
  const db = await getDb();
  const q = query(
    collection(db, "auditLogs"),
    orderBy("performedAt", "desc"),
    limit(maxResults)
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Omit<AuditLogEntry, "id">) }));
}

export async function listAuditLogsByEntity(
  entityType: AuditEntityType,
  entityId: string
): Promise<AuditLogEntry[]> {
  const db = await getDb();
  const q = query(
    collection(db, "auditLogs"),
    where("entityType", "==", entityType),
    where("entityId", "==", entityId),
    orderBy("performedAt", "desc")
  );
  const snap = await getDocs(q);
  return snap.docs.map((d) => ({ id: d.id, ...(d.data() as Omit<AuditLogEntry, "id">) }));
}
