import React, { useEffect, useState } from "react";
import type { Quote, QuoteCurrency, QuoteLanguage } from "../types";
import {
  generateQuoteShareToken,
  getQuoteById,
  revokeQuoteShareToken,
} from "../../../sessionServices/quotes/quotesService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  quoteId: string;
}

const CURRENCIES: QuoteCurrency[] = ["MXN", "CAD", "USD"];
const LANGUAGES: { value: QuoteLanguage; label: string }[] = [
  { value: "en", label: "English" },
  { value: "fr", label: "Français" },
  { value: "es", label: "Español" },
];

export function QuoteSharePanel({ quoteId }: Props) {
  const { user } = useAuth();
  const [quote, setQuote] = useState<(Quote & { id: string }) | null>(null);
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [copied, setCopied] = useState(false);
  const [currency, setCurrency] = useState<QuoteCurrency>("CAD");
  const [language, setLanguage] = useState<QuoteLanguage>("en");

  async function load() {
    const data = await getQuoteById(quoteId);
    setQuote(data);
    setLoading(false);
  }

  useEffect(() => { load(); }, [quoteId]);

  const shareUrl =
    typeof window !== "undefined" && quote?.shareToken
      ? `${window.location.origin}/app/quote/${quote.shareToken}?lang=${language}&currency=${currency}`
      : null;

  async function handleGenerate() {
    if (!user) return;
    setWorking(true);
    const token = await generateQuoteShareToken(quoteId, user.uid);
    await writeAuditLog({
      entityType: "quote",
      entityId: quoteId,
      action: "share",
      after: { shareToken: token, status: "sent" },
      performedBy: user.uid,
    });
    setWorking(false);
    load();
  }

  async function handleRevoke() {
    if (!user || !confirm("Revoke this link? The client will no longer be able to access the quote.")) return;
    setWorking(true);
    await revokeQuoteShareToken(quoteId, user.uid);
    await writeAuditLog({
      entityType: "quote",
      entityId: quoteId,
      action: "status_change",
      before: { status: "sent" },
      after: { shareToken: null },
      performedBy: user.uid,
    });
    setWorking(false);
    load();
  }

  async function handleCopy() {
    if (!shareUrl) return;
    await navigator.clipboard.writeText(shareUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  if (loading) return null;

  return (
    <div className="space-y-3">
      <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-700">
        Share with client
      </h3>

      {quote?.shareToken ? (
        <div className="space-y-3 rounded-xl bg-green-50 p-4 ring-1 ring-green-100">
          <p className="text-xs font-medium text-green-700">Active share link</p>

          {/* Currency + Language selectors */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <label className="text-xs font-medium text-gray-600">Currency</label>
              <select
                value={currency}
                onChange={(e) => setCurrency(e.target.value as QuoteCurrency)}
                className="w-full rounded-lg border border-gray-300 px-2 py-1.5 text-sm focus:outline-none"
              >
                {CURRENCIES.map((c) => (
                  <option key={c} value={c}>{c}</option>
                ))}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-xs font-medium text-gray-600">Language</label>
              <select
                value={language}
                onChange={(e) => setLanguage(e.target.value as QuoteLanguage)}
                className="w-full rounded-lg border border-gray-300 px-2 py-1.5 text-sm focus:outline-none"
              >
                {LANGUAGES.map((l) => (
                  <option key={l.value} value={l.value}>{l.label}</option>
                ))}
              </select>
            </div>
          </div>

          {/* URL */}
          <div className="flex items-center gap-2">
            <code className="flex-1 truncate rounded bg-white px-2 py-1 text-xs text-gray-700 ring-1 ring-gray-200">
              {shareUrl}
            </code>
            <button
              onClick={handleCopy}
              className="shrink-0 rounded-lg bg-green-700 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-green-800"
            >
              {copied ? "Copied!" : "Copy"}
            </button>
          </div>
          <button
            onClick={handleRevoke}
            disabled={working}
            className="text-xs text-red-500 underline hover:text-red-700 disabled:opacity-50"
          >
            Revoke link
          </button>
        </div>
      ) : (
        <div className="rounded-xl bg-gray-50 p-4 ring-1 ring-gray-200">
          <p className="mb-3 text-xs text-gray-500">
            Generate a secure link to share this quote with the client. No login required.
          </p>
          <button
            onClick={handleGenerate}
            disabled={working}
            className="rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
          >
            {working ? "Generating…" : "Generate share link"}
          </button>
        </div>
      )}
    </div>
  );
}
