import { navigate } from "gatsby";
import React, { useCallback, useEffect, useState } from "react";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { Quote, QuoteItem, UserProfile } from "../types";
import { getQuoteById } from "../../../sessionServices/quotes/quotesService";
import { deleteQuoteItem, listItemsByQuote, updateQuoteItem } from "../../../sessionServices/quotes/quoteItemsService";
import { getUserById } from "../../../sessionServices/users/usersService";
import { QuoteItemForm } from "./QuoteItemForm";
import { QuoteSharePanel } from "./QuoteSharePanel";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  quoteId: string;
}

type QuoteWithId = Quote & { id: string };
type QuoteItemWithId = QuoteItem & { id: string };

const STATUS_BADGE: Record<string, string> = {
  draft: "bg-gray-100 text-gray-600",
  sent: "bg-blue-100 text-blue-700",
  approved: "bg-green-100 text-green-700",
  rejected: "bg-red-100 text-red-600",
  expired: "bg-yellow-100 text-yellow-700",
};

const CURRENCY_SYMBOL: Record<string, string> = {
  MXN: "MX$",
  CAD: "CA$",
  USD: "US$",
};

// ─── Sortable row ─────────────────────────────────────────────────────────────

interface SortableRowProps {
  item: QuoteItemWithId;
  index: number;
  isEditing: boolean;
  quoteId: string;
  onEdit: () => void;
  onDelete: () => void;
  onSaved: () => void;
  onCancelEdit: () => void;
  disabled: boolean;
}

function SortableRow({
  item,
  index,
  isEditing,
  quoteId,
  onEdit,
  onDelete,
  onSaved,
  onCancelEdit,
  disabled,
}: SortableRowProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: item.id, disabled });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
    background: isDragging ? "#f3f4f6" : undefined,
  };

  if (isEditing) {
    return (
      <tr ref={setNodeRef} style={style}>
        <td colSpan={6} className="p-3">
          <QuoteItemForm
            quoteId={quoteId}
            nextSortOrder={item.sortOrder}
            existing={item}
            onSaved={onSaved}
            onCancel={onCancelEdit}
          />
        </td>
      </tr>
    );
  }

  return (
    <tr ref={setNodeRef} style={style} className="align-top">
      {/* Drag handle */}
      <td className="px-3 py-3 w-8">
        <div className="flex items-center gap-1">
          <button
            {...attributes}
            {...listeners}
            className="cursor-grab active:cursor-grabbing touch-none text-gray-300 hover:text-gray-500 transition"
            aria-label="Drag to reorder"
            tabIndex={-1}
          >
            <svg width="12" height="16" viewBox="0 0 12 16" fill="currentColor">
              <circle cx="3" cy="3" r="1.5" />
              <circle cx="9" cy="3" r="1.5" />
              <circle cx="3" cy="8" r="1.5" />
              <circle cx="9" cy="8" r="1.5" />
              <circle cx="3" cy="13" r="1.5" />
              <circle cx="9" cy="13" r="1.5" />
            </svg>
          </button>
          <span className="text-xs text-gray-400">{index + 1}</span>
        </div>
      </td>
      <td className="px-4 py-3 max-w-sm">
        <p className="text-gray-900 whitespace-pre-wrap">{item.description}</p>
        {item.descriptionFr && (
          <p className="mt-1 text-xs text-gray-400 whitespace-pre-wrap">
            <span className="font-medium">FR:</span> {item.descriptionFr}
          </p>
        )}
        {item.descriptionEs && (
          <p className="mt-1 text-xs text-gray-400 whitespace-pre-wrap">
            <span className="font-medium">ES:</span> {item.descriptionEs}
          </p>
        )}
      </td>
      <td className="px-4 py-3 text-right text-gray-700 font-mono">
        {item.priceMXN != null ? `${CURRENCY_SYMBOL.MXN} ${item.priceMXN.toFixed(2)}` : "—"}
      </td>
      <td className="px-4 py-3 text-right text-gray-700 font-mono">
        {item.priceCAD != null ? `${CURRENCY_SYMBOL.CAD} ${item.priceCAD.toFixed(2)}` : "—"}
      </td>
      <td className="px-4 py-3 text-right text-gray-700 font-mono">
        {item.priceUSD != null ? `${CURRENCY_SYMBOL.USD} ${item.priceUSD.toFixed(2)}` : "—"}
      </td>
      <td className="px-4 py-3 text-right">
        <div className="flex justify-end gap-3">
          <button
            onClick={onEdit}
            className="text-xs text-gray-400 underline hover:text-gray-700"
          >Edit</button>
          <button
            onClick={onDelete}
            className="text-xs text-red-400 underline hover:text-red-600"
          >Delete</button>
        </div>
      </td>
    </tr>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export function QuoteDetail({ quoteId }: Props) {
  const { user } = useAuth();
  const [quote, setQuote] = useState<QuoteWithId | null>(null);
  const [items, setItems] = useState<QuoteItemWithId[]>([]);
  const [client, setClient] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [addingItem, setAddingItem] = useState(false);
  const [editingItem, setEditingItem] = useState<QuoteItemWithId | null>(null);
  const [saving, setSaving] = useState(false);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  const load = useCallback(async () => {
    const [quoteData, itemsData] = await Promise.all([
      getQuoteById(quoteId),
      listItemsByQuote(quoteId),
    ]);
    setQuote(quoteData);
    setItems(itemsData);
    if (quoteData?.userId) {
      const clientData = await getUserById(quoteData.userId);
      setClient(clientData);
    }
    setLoading(false);
  }, [quoteId]);

  useEffect(() => { load(); }, [load]);

  async function handleDeleteItem(item: QuoteItemWithId) {
    if (!confirm("Delete this item?")) return;
    await deleteQuoteItem(item.id);
    load();
  }

  async function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over || active.id === over.id || !user) return;

    const oldIndex = items.findIndex((i) => i.id === active.id);
    const newIndex = items.findIndex((i) => i.id === over.id);
    const reordered = arrayMove(items, oldIndex, newIndex);

    // Optimistic update
    setItems(reordered);
    setSaving(true);

    // Persist new sortOrder for each item that changed position
    const updates = reordered
      .map((item, idx) => ({ item, newOrder: idx + 1 }))
      .filter(({ item, newOrder }) => item.sortOrder !== newOrder);

    await Promise.all(
      updates.map(({ item, newOrder }) =>
        updateQuoteItem(item.id, { sortOrder: newOrder, updatedBy: user.uid })
      )
    );

    // Update local state with new sortOrders
    setItems(reordered.map((item, idx) => ({ ...item, sortOrder: idx + 1 })));
    setSaving(false);
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (!quote) {
    return <p className="text-sm text-gray-500">Quote not found.</p>;
  }

  const totalMXN = items.reduce((s, i) => s + (i.priceMXN ?? 0), 0);
  const totalCAD = items.reduce((s, i) => s + (i.priceCAD ?? 0), 0);
  const totalUSD = items.reduce((s, i) => s + (i.priceUSD ?? 0), 0);
  const isDraggable = !addingItem && !editingItem;

  return (
    <div className="space-y-6">
      {/* Header card */}
      <div className="flex flex-wrap items-start justify-between gap-4 rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <h2 className="text-lg font-semibold text-gray-900">{quote.title}</h2>
            <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[quote.status] ?? "bg-gray-100 text-gray-600"}`}>
              {quote.status}
            </span>
          </div>
          {client && (
            <p className="text-sm text-gray-500">
              Client: <span className="font-medium text-gray-800">{client.fullName}</span> · {client.email}
            </p>
          )}
          {quote.validUntil && (
            <p className="text-xs text-gray-400">
              Valid until: {(quote.validUntil as { toDate: () => Date }).toDate().toLocaleDateString("en-CA")}
            </p>
          )}
          {quote.internalNotes && (
            <p className="mt-2 rounded-lg bg-yellow-50 px-3 py-1.5 text-xs text-yellow-800">
              Internal note: {quote.internalNotes}
            </p>
          )}
        </div>
        <button
          onClick={() => navigate(`/admin/quotes/${quoteId}/edit`)}
          className="rounded-lg border border-gray-300 px-4 py-1.5 text-sm font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Edit quote
        </button>
      </div>

      {/* Items table */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-700">
              Items ({items.length})
            </h3>
            {saving && (
              <span className="text-xs text-gray-400">Saving order…</span>
            )}
          </div>
          {!addingItem && !editingItem && (
            <button
              onClick={() => setAddingItem(true)}
              className="rounded-lg bg-gray-900 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-gray-700"
            >
              + Add item
            </button>
          )}
        </div>

        {addingItem && (
          <QuoteItemForm
            quoteId={quoteId}
            nextSortOrder={items.length + 1}
            onSaved={() => { setAddingItem(false); load(); }}
            onCancel={() => setAddingItem(false)}
          />
        )}

        {items.length === 0 && !addingItem ? (
          <p className="text-sm text-gray-400">No items yet. Add the first item.</p>
        ) : (
          <div className="overflow-hidden rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-gray-100 bg-gray-50 text-left text-xs font-medium uppercase tracking-wide text-gray-500">
                  <th className="px-3 py-3 w-12" />
                  <th className="px-4 py-3">Description (EN / FR / ES)</th>
                  <th className="px-4 py-3 text-right">MXN</th>
                  <th className="px-4 py-3 text-right">CAD</th>
                  <th className="px-4 py-3 text-right">USD</th>
                  <th className="px-4 py-3" />
                </tr>
              </thead>
              <DndContext
                sensors={sensors}
                collisionDetection={closestCenter}
                onDragEnd={handleDragEnd}
              >
                <SortableContext
                  items={items.map((i) => i.id)}
                  strategy={verticalListSortingStrategy}
                >
                  <tbody className="divide-y divide-gray-100">
                    {items.map((item, idx) => (
                      <SortableRow
                        key={item.id}
                        item={item}
                        index={idx}
                        isEditing={editingItem?.id === item.id}
                        quoteId={quoteId}
                        disabled={!isDraggable}
                        onEdit={() => { setEditingItem(item); setAddingItem(false); }}
                        onDelete={() => handleDeleteItem(item)}
                        onSaved={() => { setEditingItem(null); load(); }}
                        onCancelEdit={() => setEditingItem(null)}
                      />
                    ))}

                    {/* Totals row */}
                    {items.length > 0 && (
                      <tr className="bg-gray-50 font-semibold text-gray-900">
                        <td className="px-4 py-3 text-xs uppercase text-gray-500" colSpan={2}>Total</td>
                        <td className="px-4 py-3 text-right font-mono">{CURRENCY_SYMBOL.MXN} {totalMXN.toFixed(2)}</td>
                        <td className="px-4 py-3 text-right font-mono">{CURRENCY_SYMBOL.CAD} {totalCAD.toFixed(2)}</td>
                        <td className="px-4 py-3 text-right font-mono">{CURRENCY_SYMBOL.USD} {totalUSD.toFixed(2)}</td>
                        <td />
                      </tr>
                    )}
                  </tbody>
                </SortableContext>
              </DndContext>
            </table>
          </div>
        )}
      </div>

      {/* Share panel */}
      <div className="rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200">
        <QuoteSharePanel quoteId={quoteId} />
      </div>
    </div>
  );
}
