import React, { useEffect, useState } from "react";
import type { QuoteItem } from "../types";
import {
  createQuoteItem,
  updateQuoteItem,
} from "../../../sessionServices/quotes/quoteItemsService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  quoteId: string;
  nextSortOrder: number;
  existing?: QuoteItem & { id: string };
  onSaved: () => void;
  onCancel: () => void;
}

export function QuoteItemForm({ quoteId, nextSortOrder, existing, onSaved, onCancel }: Props) {
  const { user } = useAuth();
  const isEdit = !!existing;

  const [description, setDescription] = useState(existing?.description ?? "");
  const [descriptionFr, setDescriptionFr] = useState(existing?.descriptionFr ?? "");
  const [descriptionEs, setDescriptionEs] = useState(existing?.descriptionEs ?? "");
  const [priceMXN, setPriceMXN] = useState(existing?.priceMXN?.toString() ?? "");
  const [priceCAD, setPriceCAD] = useState(existing?.priceCAD?.toString() ?? "");
  const [priceUSD, setPriceUSD] = useState(existing?.priceUSD?.toString() ?? "");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    if (!description.trim()) {
      setError("Description (EN) is required.");
      return;
    }
    setSaving(true);
    setError(null);
    try {
      if (isEdit) {
        await updateQuoteItem(existing!.id, {
          description: description.trim(),
          descriptionFr: descriptionFr.trim() || undefined,
          descriptionEs: descriptionEs.trim() || undefined,
          priceMXN: parseFloat(priceMXN) || 0,
          priceCAD: parseFloat(priceCAD) || 0,
          priceUSD: parseFloat(priceUSD) || 0,
          updatedBy: user.uid,
        });
      } else {
        await createQuoteItem({
          quoteId,
          sortOrder: nextSortOrder,
          description: description.trim(),
          descriptionFr: descriptionFr.trim() || undefined,
          descriptionEs: descriptionEs.trim() || undefined,
          priceMXN: parseFloat(priceMXN) || 0,
          priceCAD: parseFloat(priceCAD) || 0,
          priceUSD: parseFloat(priceUSD) || 0,
          createdBy: user.uid,
        });
      }
      onSaved();
    } catch {
      setError("Could not save item. Please try again.");
      setSaving(false);
    }
  }

  const fieldCls = "w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-gray-400";
  const textareaCls = `${fieldCls} resize-y`;
  const priceCls = "w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-gray-400";

  return (
    <form onSubmit={handleSubmit} className="rounded-xl bg-gray-50 p-4 ring-1 ring-gray-200 space-y-4">
      <p className="text-xs font-semibold uppercase tracking-wide text-gray-500">
        {isEdit ? "Edit item" : "New item"}
      </p>

      {/* Descriptions */}
      <div className="grid gap-3 lg:grid-cols-3">
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Description (EN) *</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            rows={4}
            className={textareaCls}
            placeholder="Describe the service or item in English…"
            required
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Description (FR)</label>
          <textarea
            value={descriptionFr}
            onChange={(e) => setDescriptionFr(e.target.value)}
            rows={4}
            className={textareaCls}
            placeholder="Décrivez le service en français…"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Description (ES)</label>
          <textarea
            value={descriptionEs}
            onChange={(e) => setDescriptionEs(e.target.value)}
            rows={4}
            className={textareaCls}
            placeholder="Describa el servicio en español…"
          />
        </div>
      </div>

      {/* Prices */}
      <div className="grid gap-3 sm:grid-cols-3">
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Price MXN ($)</label>
          <input
            type="number"
            min="0"
            step="0.01"
            value={priceMXN}
            onChange={(e) => setPriceMXN(e.target.value)}
            className={priceCls}
            placeholder="0.00"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Price CAD ($)</label>
          <input
            type="number"
            min="0"
            step="0.01"
            value={priceCAD}
            onChange={(e) => setPriceCAD(e.target.value)}
            className={priceCls}
            placeholder="0.00"
          />
        </div>
        <div className="space-y-1">
          <label className="text-xs font-medium text-gray-600">Price USD ($)</label>
          <input
            type="number"
            min="0"
            step="0.01"
            value={priceUSD}
            onChange={(e) => setPriceUSD(e.target.value)}
            className={priceCls}
            placeholder="0.00"
          />
        </div>
      </div>

      {error && <p className="text-xs text-red-600">{error}</p>}

      <div className="flex gap-3">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-4 py-1.5 text-xs font-medium text-white transition hover:bg-gray-700 disabled:opacity-60"
        >
          {saving ? "Saving…" : isEdit ? "Save changes" : "Add item"}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-gray-300 px-4 py-1.5 text-xs font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}
